package com.securebiz.copilot.service;import com.fasterxml.jackson.databind.*;import com.securebiz.copilot.config.LlmProperties;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.*;
@Component public class LlmClient{private final LlmProperties p;private final ObjectMapper json;private final RestClient client;public LlmClient(LlmProperties p,ObjectMapper json){this.p=p;this.json=json;this.client=RestClient.create();}public Result complete(String system,String user){if(!p.enabled()||p.model()==null||p.model().isBlank())throw new IllegalStateException("LLM copilot is disabled or no model is configured");Map<String,Object>body=Map.of("model",p.model(),"temperature",0.1,"messages",List.of(Map.of("role","system","content",system),Map.of("role","user","content",user)));try{var request=client.post().uri(p.endpoint()).contentType(MediaType.APPLICATION_JSON);if(p.apiKey()!=null&&!p.apiKey().isBlank())request=request.header(HttpHeaders.AUTHORIZATION,"Bearer "+p.apiKey());JsonNode response=request.body(body).retrieve().body(JsonNode.class);String answer=response.path("choices").path(0).path("message").path("content").asText();if(answer.isBlank())throw new IllegalStateException("LLM returned an empty answer");return new Result(answer,p.provider(),p.model());}catch(Exception e){throw new IllegalStateException("LLM provider request failed",e);}}public record Result(String answer,String provider,String model){}}
